			log.Fatal(err)
		}
		fmt.Println(" -", name)
	}

	// Query schema of wallets
	var sqlSchema string
	err = db.QueryRow("SELECT sql FROM sqlite_master WHERE type='table' AND name='wallets'").Scan(&sqlSchema)
	if err == nil {
		fmt.Printf("\nwallets schema:\n%s\n", sqlSchema)
	}

